package vn.eventplatform.ad.controller;
import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.http.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import org.springframework.web.multipart.MultipartFile; import vn.eventplatform.ad.dto.*; import vn.eventplatform.ad.service.*; import vn.eventplatform.common.dto.ApiResponse; import java.math.BigDecimal; import java.util.*;
@RestController @RequiredArgsConstructor public class AdController { private final AdService service; private final CloudinaryUploadService cloudinary; private UUID me(Authentication a){return UUID.fromString(a.getPrincipal().toString());}
 @GetMapping("/api/v1/public/banners") public ResponseEntity<ApiResponse<List<Responses.BannerResponse>>> publicBanners(){return ResponseEntity.ok(ApiResponse.ok(service.publicBanners()));}
 @GetMapping("/api/v1/admin/ad-packages") @PreAuthorize("hasRole('ADMIN')") public ResponseEntity<ApiResponse<List<Responses.PackageResponse>>> packages(){return ResponseEntity.ok(ApiResponse.ok(service.packageAll()));}
 @PostMapping("/api/v1/admin/ad-packages") @PreAuthorize("hasRole('ADMIN')") public ResponseEntity<ApiResponse<Responses.PackageResponse>> createPackage(@Valid @RequestBody Requests.PackageRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(ApiResponse.ok("Tạo gói quảng cáo thành công",service.packageCreate(r)));}
 @PutMapping("/api/v1/admin/ad-packages/{id}") @PreAuthorize("hasRole('ADMIN')") public ResponseEntity<ApiResponse<Responses.PackageResponse>> updatePackage(@PathVariable UUID id,@Valid @RequestBody Requests.PackageRequest r){return ResponseEntity.ok(ApiResponse.ok("Cập nhật gói quảng cáo thành công",service.packageUpdate(id,r)));}
 @DeleteMapping("/api/v1/admin/ad-packages/{id}") @PreAuthorize("hasRole('ADMIN')") public ResponseEntity<ApiResponse<Void>> deletePackage(@PathVariable UUID id){service.packageDelete(id);return ResponseEntity.ok(ApiResponse.ok("Đã xóa gói quảng cáo",null));}
 @PostMapping("/api/v1/organizer/ad-campaigns") @PreAuthorize("hasRole('ORGANIZER')") public ResponseEntity<ApiResponse<Responses.CampaignResponse>> register(Authentication a,@Valid @RequestBody Requests.CampaignRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(ApiResponse.ok("Đăng ký campaign thành công",service.register(me(a),r)));}
 @GetMapping("/api/v1/organizer/ad-campaigns") @PreAuthorize("hasRole('ORGANIZER')") public ResponseEntity<ApiResponse<List<Responses.CampaignResponse>>> mine(Authentication a){return ResponseEntity.ok(ApiResponse.ok(service.organizerCampaigns(me(a))));}
 @PostMapping("/api/v1/admin/ad-campaigns/{id}/approve") @PreAuthorize("hasRole('ADMIN')") public ResponseEntity<ApiResponse<Responses.CampaignResponse>> approve(@PathVariable UUID id){return ResponseEntity.ok(ApiResponse.ok("Đã duyệt campaign",service.approve(id)));}
 @PostMapping("/api/v1/admin/ad-campaigns/{id}/reject") @PreAuthorize("hasRole('ADMIN')") public ResponseEntity<ApiResponse<Responses.CampaignResponse>> reject(@PathVariable UUID id,@RequestBody Requests.DecisionRequest r){return ResponseEntity.ok(ApiResponse.ok("Đã từ chối campaign",service.reject(id,r.reason())));}
 @PostMapping("/internal/v1/ad-campaigns/{id}/settlement") public ResponseEntity<ApiResponse<BigDecimal>> settlement(@PathVariable UUID id){service.publishSettlement(id);return ResponseEntity.ok(ApiResponse.ok("Đã publish settlement",service.postpaidFee(id)));}
 @PostMapping("/api/v1/admin/banners") @PreAuthorize("hasRole('ADMIN')") public ResponseEntity<ApiResponse<Responses.BannerResponse>> banner(@Valid @RequestBody Requests.BannerRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(ApiResponse.ok("Tạo banner thành công",service.banner(r)));}
 @PostMapping(value="/api/v1/admin/banners/upload",consumes=MediaType.MULTIPART_FORM_DATA_VALUE) @PreAuthorize("hasRole('ADMIN')") public ResponseEntity<ApiResponse<String>> upload(@RequestParam("file") MultipartFile file){return ResponseEntity.status(HttpStatus.CREATED).body(ApiResponse.ok("Upload ảnh thành công",cloudinary.upload(file)));}
 @PutMapping("/api/v1/admin/banners/{id}") @PreAuthorize("hasRole('ADMIN')") public ResponseEntity<ApiResponse<Responses.BannerResponse>> bannerUpdate(@PathVariable UUID id,@Valid @RequestBody Requests.BannerRequest r){return ResponseEntity.ok(ApiResponse.ok("Cập nhật banner thành công",service.bannerUpdate(id,r)));}
 @PostMapping("/api/v1/admin/banners/{id}/approve-image") @PreAuthorize("hasRole('ADMIN')") public ResponseEntity<ApiResponse<Responses.BannerResponse>> imageApprove(@PathVariable UUID id){return ResponseEntity.ok(ApiResponse.ok("Đã duyệt ảnh banner",service.approveImage(id)));}
 @DeleteMapping("/api/v1/admin/banners/{id}") @PreAuthorize("hasRole('ADMIN')") public ResponseEntity<ApiResponse<Void>> bannerDelete(@PathVariable UUID id){service.deleteBanner(id);return ResponseEntity.ok(ApiResponse.ok("Đã xóa banner",null));}}
